export default async function Page() {
  const [user, products, reviews] = await Promise.all([
    fetchUser(),
    fetchProducts(),
    fetchReviews(),
  ]);
}
```

## Summary of Techniques
- Use `Promise.all()` for independent async operations
- Fire-and-forget non-critical operations (don't await analytics)
- Remove unnecessary data fetching from API routes
- Serialize only when there are true data dependencies

# Next.js Bundle Size Reduction

## Problem
Large JavaScript bundles slow down page load times, especially on client components. Heavy libraries like `lodash` (5MB) and `mathjs` (18MB) dramatically increase bundle size when simpler alternatives exist.

## Key Patterns

### 1. Replace `lodash` with Native JavaScript

Lodash's full bundle is ~70KB minified+gzipped. Most utility functions have native JS equivalents.

**Before** (imports entire lodash):
```typescript
import { sortBy, meanBy, sumBy, maxBy, minBy } from 'lodash';

const sorted = sortBy(products, ['price']);
const avg = meanBy(products, 'price');
const total = sumBy(products, 'reviews');
const best = maxBy(products, 'rating');
const cheapest = minBy(products, 'price');
```

**After** (native JS, zero bundle cost):
```typescript
const sorted = [...products].sort((a, b) => a.price - b.price);
const avg = products.reduce((sum, p) => sum + p.price, 0) / products.length;
const total = products.reduce((sum, p) => sum + p.reviews, 0);
const best = products.reduce((max, p) => p.rating > max.rating ? p : max);
const cheapest = products.reduce((min, p) => p.price < min.price ? p : min);
```

### 2. Replace `mathjs` with Simple Statistical Functions

`mathjs` is a comprehensive math library (>500KB minified+gzipped). For basic statistics, write simple utility functions:

**Before** (imports heavy mathjs):
```typescript
import { mean, std, median, quantileSeq, variance } from 'mathjs';

const avg = mean(values);
const med = median(values);
const stdDev = std(values);
const v = variance(values);
const q1 = quantileSeq(values, 0.25);
```

**After** (lightweight custom functions):
```typescript
function calcMean(arr: number[]): number {
  return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

function calcMedian(arr: number[]): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

function calcVariance(arr: number[]): number {
  const m = calcMean(arr);
  return arr.reduce((sum, v) => sum + (v - m) ** 2, 0) / arr.length;
}

function calcStd(arr: number[]): number {
  return Math.sqrt(calcVariance(arr));
}

function calcQuantile(arr: number[], q: number): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}
```

### 3. Dynamic Imports for Heavy Components

Use `next/dynamic` to lazy-load components that aren't immediately visible:

```typescript
import dynamic from 'next/dynamic';

const HeavyComponent = dynamic(() => import('./HeavyComponent'), {
  loading: () => <p>Loading...</p>,
});
```

### 4. Tree-Shaking Considerations

Even named imports from lodash (`import { sortBy } from 'lodash'`) pull in the entire library because lodash is a CommonJS module. To tree-shake properly, you need:

```typescript
// This does NOT tree-shake:
import { sortBy } from 'lodash';

// This does tree-shake (per-function import):
import sortBy from 'lodash/sortBy';
```

But the best approach is to just use native JS instead.

### 5. Analyzing Bundle Size

Use Next.js built-in bundle analyzer:

```bash
npm install @next/bundle-analyzer
```

```javascript
// next.config.js
const withBundleAnalyzer = require('@next/bundle-analyzer')({
  enabled: process.env.ANALYZE === 'true',
});
module.exports = withBundleAnalyzer({});
```

```bash
ANALYZE=true npm run build
```

## Summary
- Replace lodash functions with native JS array methods
- Replace mathjs with ~30 lines of custom statistics functions
- Use dynamic imports for conditionally rendered heavy components
- The goal is to eliminate unnecessary dependencies from the client bundle

# React Rendering Optimization

## Problem
Excessive re-rendering in React components causes sluggish UIs. Common causes include: recalculating expensive operations on every render, passing new function/object references as props, and not memoizing derived data.

## Key Patterns

### 1. Memoize Expensive Computations with `useMemo`

**Bad** - O(n*m) recalculation on every render:
```typescript
function ProductList({ products, reviews }) {
  const getReviewCount = (productId: string) => {
    return reviews.filter(r => r.productId === productId).length; // O(m) per call
  };

  return products.map(p => (
    <ProductCard reviewCount={getReviewCount(p.id)} /> // Called n times = O(n*m)
  ));
}
```

**Good** - Pre-compute a lookup map once with `useMemo`:
```typescript
function ProductList({ products, reviews }) {
  const reviewCountMap = useMemo(() => {
    const map: Record<string, number> = {};
    for (const r of reviews) {
      map[r.productId] = (map[r.productId] || 0) + 1;
    }
    return map;
  }, [reviews]); // Only recomputes when reviews change

  return products.map(p => (
    <ProductCard reviewCount={reviewCountMap[p.id] || 0} />
  ));
}
```

### 2. Stabilize Callbacks with `useCallback`

**Bad** - New function reference on every render causes child re-renders:
```typescript
function ProductList() {
  const [cart, setCart] = useState([]);

  const handleAddToCart = (productId: string) => {
    setCart(prev => [...prev, productId]); // New function every render
  };

  return products.map(p => (
    <ProductCard onAddToCart={handleAddToCart} /> // Always gets new prop
  ));
}
```

**Good** - Stable reference:
```typescript
function ProductList() {
  const [cart, setCart] = useState([]);

  const handleAddToCart = useCallback((productId: string) => {
    setCart(prev => [...prev, productId]);
  }, []); // Stable reference across renders

  return products.map(p => (
    <ProductCard onAddToCart={handleAddToCart} />
  ));
}
```

### 3. Prevent Unnecessary Child Re-renders with `React.memo`

**Bad** - ProductCard re-renders whenever parent re-renders:
```typescript
export function ProductCard({ product, reviewCount, onAddToCart, isInCart }) {
  return <div>...</div>;
}
```

**Good** - Only re-renders when props actually change:
```typescript
export const ProductCard = React.memo(function ProductCard({
  product, reviewCount, onAddToCart, isInCart
}) {
  return <div>...</div>;
});
```

### 4. Memoize Filtered/Sorted Lists

**Bad** - Recalculates on every render:
```typescript
const filteredProducts = products
  .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
  .filter(p => p.inStock)
  .sort((a, b) => a.price - b.price);
```

**Good** - Only recalculates when dependencies change:
```typescript
const filteredProducts = useMemo(() =>
  products
    .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
    .filter(p => p.inStock)
    .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating),
  [products, filter, sortBy]
);
```

### 5. Avoid Inline Object/Array Literals as Props

**Bad**:
```typescript
<Component style={{ color: 'red' }} /> // New object every render
<Component items={[1, 2, 3]} /> // New array every render
```

**Good**:
```typescript
const style = useMemo(() => ({ color: 'red' }), []);
const items = useMemo(() => [1, 2, 3], []);
<Component style={style} items={items} />
```

## Complete Optimization Checklist
1. Use `useMemo` for expensive derived state (filtering, sorting, mapping)
2. Use `useCallback` for functions passed as props to child components
3. Use `React.memo` on components that receive stable props
4. Pre-compute lookup maps instead of repeated array searches
5. Memoize filtered/sorted results

# Next.js Dynamic Imports and Code Splitting

## Problem
When all components are statically imported, the entire page bundle includes code for components that may not be immediately needed. This increases initial load time, especially for tab-based UIs where only one tab is visible at a time.

## Key Patterns

### 1. Dynamic Import with `next/dynamic`

Use `next/dynamic` for components that aren't needed on initial render:

```typescript
import dynamic from 'next/dynamic';

const HeavyComponent = dynamic(() => import('./HeavyComponent'), {
  loading: () => <div>Loading...</div>,
});

export default function Page() {
  return <HeavyComponent />;
}
```

### 2. Tab-Based Lazy Loading

For tabbed interfaces, only load the active tab's component:

**Bad** - Both tabs loaded upfront:
```typescript
import { OverviewTab } from './OverviewTab';
import { AdvancedTab } from './AdvancedTab'; // Heavy, uses mathjs

export default function Page() {
  const [tab, setTab] = useState('overview');
  return tab === 'overview' ? <OverviewTab /> : <AdvancedTab />;
}
```

**Good** - Heavy tab loaded on demand:
```typescript
import dynamic from 'next/dynamic';
import { OverviewTab } from './OverviewTab'; // Lightweight, load immediately

const AdvancedTab = dynamic(() => import('./AdvancedTab'), {
  loading: () => <div>Loading analysis...</div>,
});

export default function Page() {
  const [tab, setTab] = useState('overview');
  return tab === 'overview' ? <OverviewTab /> : <AdvancedTab />;
}
```

### 3. Extracting Components for Dynamic Import

To use `dynamic()`, the component must be in a separate file with a default export:

```typescript
// components/AdvancedAnalysis.tsx
'use client';
export default function AdvancedAnalysis({ products }) {
  // Heavy logic with mathjs here
  return <div>...</div>;
}
```

```typescript
// app/compare/page.tsx
const AdvancedAnalysis = dynamic(() => import('@/components/AdvancedAnalysis'));
```

### 4. SSR Control

Disable SSR for client-only components:

```typescript
const ClientOnlyChart = dynamic(() => import('./Chart'), {
  ssr: false,
  loading: () => <div>Loading chart...</div>,
});
```

### 5. Benefits
- Reduces initial JavaScript bundle size
- Defers loading of heavy dependencies (e.g., mathjs is only loaded when the Advanced tab is clicked)
- Improves Time to Interactive (TTI) and First Contentful Paint (FCP)
- Each dynamically imported component creates a separate webpack chunk

## When to Use Dynamic Imports
- Components behind tabs, modals, or accordions
- Components using heavy third-party libraries
- Components below the fold (not initially visible)
- Admin/dashboard panels not shown to all users

# Next.js Server Component Patterns

## Problem
Incorrect use of `'use client'` and `force-dynamic` can lead to unnecessary client-side JavaScript and missed caching opportunities.

## Key Patterns

### 1. Avoid `force-dynamic` When Unnecessary

`force-dynamic` disables all caching and forces server-side rendering on every request:

**Bad** - Disables caching entirely:
```typescript
export const dynamic = 'force-dynamic';

export default async function Page() {
  const data = await fetchData();
  return <div>{data}</div>;
}
```

**Good** - Remove force-dynamic when data can be cached or revalidated. If data changes occasionally, use ISR:
```typescript
// Remove force-dynamic to allow default caching behavior
// Next.js will cache the page and serve it from cache

export default async function Page() {
  const data = await fetchData();
  return <div>{data}</div>;
}
```

### 2. Keep Components as Server Components When Possible

Server components don't ship JavaScript to the client:

**Bad** - Unnecessary client component:
```typescript
'use client';
// This component only displays data, no interactivity
export function StaticDisplay({ data }) {
  return <div>{data.name}</div>;
}
```

**Good** - Server component (zero client JS):
```typescript
// No 'use client' needed for display-only components
export function StaticDisplay({ data }) {
  return <div>{data.name}</div>;
}
```

### 3. Push `'use client'` Boundary Down

Only wrap the interactive parts in client components:

**Bad** - Entire page is a client component:
```typescript
'use client';
export default function Page() {
  const [tab, setTab] = useState('a');
  return (
    <div>
      <h1>Static Title</h1>
      <p>Long static description...</p>
      <button onClick={() => setTab('b')}>Switch</button>
      {tab === 'a' ? <TabA /> : <TabB />}
    </div>
  );
}
```

**Good** - Only interactive parts are client components:
```typescript
// Server component page
export default function Page() {
  return (
    <div>
      <h1>Static Title</h1>
      <p>Long static description...</p>
      <TabSwitcher /> {/* Only this is a client component */}
    </div>
  );
}
```

### 4. Server Component Data Fetching Best Practices

```typescript
// In server components, fetch calls are automatically deduped by Next.js
// when using the same URL within a single render pass

export default async function Page() {
  // These run on the server - no bundle size impact from imports
  const [users, posts] = await Promise.all([
    fetchUsers(),
    fetchPosts(),
  ]);

  return (
    <main>
      <UserList users={users} />      {/* Server component */}
      <InteractiveForm />              {/* Client component */}
    </main>
  );
}
```

## Summary
- Remove `force-dynamic` unless truly needed (e.g., per-user authenticated data)
- Keep components as server components when they don't need interactivity
- Push `'use client'` boundaries as deep as possible
- Use `Promise.all()` for parallel server-side data fetching

