'use client';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

function calcMean(arr: number[]): number {
  return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

function calcMedian(arr: number[]): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

function calcVariance(arr: number[]): number {
  const m = calcMean(arr);
  return arr.reduce((sum, v) => sum + (v - m) ** 2, 0) / arr.length;
}

function calcStd(arr: number[]): number {
  return Math.sqrt(calcVariance(arr));
}

function calcQuantile(arr: number[], q: number): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}

export default function AdvancedAnalysis({ products }: { products: Product[] }) {
  const prices = products.map(p => p.price);
  const ratings = products.map(p => p.rating);
  const reviews = products.map(p => p.reviews);

  const priceStats = {
    mean: calcMean(prices),
    median: calcMedian(prices),
    std: calcStd(prices),
    variance: calcVariance(prices),
    q1: calcQuantile(prices, 0.25),
    q3: calcQuantile(prices, 0.75),
  };

  const ratingStats = {
    mean: calcMean(ratings),
    median: calcMedian(ratings),
    std: calcStd(ratings),
