'use client';

import { useState } from 'react';
import dynamic from 'next/dynamic';

const AdvancedAnalysis = dynamic(() => import('@/components/AdvancedAnalysis'), {
  loading: () => <div className="bg-white rounded-xl shadow-md p-6 text-center text-gray-500">Loading analysis...</div>,
});

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

// Sample products to compare
const PRODUCTS: Product[] = [
